# General Information: the 1987 Constitution of the Republic of the Philippines (text as ratified
# in 1987). No officeholders. Key first.
ITEMS = [
    # ---------- Practice Test 1 (Professional) ----------
    S(1, 1, "Article IX-B", "Under the 1987 Constitution, appointments in the civil service are made according to merit and fitness, determined as far as practicable by:",
      ["competitive examination", "the appointing officer's choice", "length of residence", "recommendation of Congress"],
      "Article IX-B, Section 2(2): appointments are made according to merit and fitness determined, as far as practicable, by competitive examination, except for policy-determining, primarily confidential or highly technical positions."),
    S(1, 2, "Article IX-B", "According to the Constitution, the civil service covers all branches, agencies and instrumentalities of the government, including government-owned or controlled corporations:",
      ["with original charters", "listed on the stock exchange", "created after 1987 only", "owned by local governments"],
      "Article IX-B, Section 2(1) covers GOCCs \"with original charters\", that is, those created by a special law. Corporations set up under the general corporation law are outside the civil service."),
    S(1, 2, "Article IX-B", "Which activity does the Constitution expressly prohibit for officers and employees in the civil service?",
      ["Partisan political campaigning", "Joining a labor organization", "Voting in national elections", "Taking a civil service exam"],
      "Article IX-B, Section 2(4) bars civil servants from engaging, directly or indirectly, in any electioneering or partisan political campaign. Section 2(5) protects their right to self-organization, so joining an organization is allowed."),
    S(1, 2, "Article XI", "Which article of the 1987 Constitution begins with \"Public office is a public trust\"?",
      ["Article XI, Accountability of Public Officers", "Article IX, Constitutional Commissions", "Article II, Declaration of Principles and State Policies", "Article III, Bill of Rights"],
      "Article XI, Section 1 opens: \"Public office is a public trust. Public officers and employees must, at all times, be accountable to the people...\""),
    S(1, 2, "Legislative department", "How many senators make up the Senate under the 1987 Constitution?",
      ["24", "12", "18", "30"],
      "Article VI, Section 2: the Senate is composed of 24 senators elected at large by the qualified voters of the Philippines. Half are elected every three years."),
    S(1, 3, "Executive department", "For how long may the President proclaim martial law or suspend the privilege of the writ of habeas corpus before Congress must extend it?",
      ["60 days", "30 days", "90 days", "48 hours"],
      "Article VII, Section 18 limits the proclamation or suspension to a period not exceeding 60 days unless Congress extends it. The President must report to Congress within 48 hours."),
    S(1, 2, "Accountability", "Which body has the exclusive power to initiate all cases of impeachment?",
      ["The House of Representatives", "The Senate", "The Supreme Court", "The Office of the Ombudsman"],
      "Article XI, Section 3: the House of Representatives has the exclusive power to initiate impeachment; the Senate has the sole power to try and decide the case."),
    S(1, 3, "Judicial department", "How many justices make up the Supreme Court, including the Chief Justice?",
      ["15", "9", "12", "14"],
      "Article VIII, Section 4(1): the Supreme Court is composed of a Chief Justice and 14 Associate Justices, 15 in all."),
    S(1, 2, "Declaration of principles", "The 1987 Constitution declares that civilian authority is, at all times, supreme over:",
      ["the military", "the courts", "the Church", "local governments"],
      "Article II, Section 3: \"Civilian authority is, at all times, supreme over the military.\""),
    S(1, 3, "Amendments", "Under Article XVII, a petition for amendment by people's initiative must be signed by at least what share of all registered voters?",
      ["12 percent", "3 percent", "5 percent", "10 percent"],
      "Article XVII, Section 2 requires at least 12% of the total registered voters, with every legislative district represented by at least 3% of its registered voters."),

    # ---------- Practice Test 2 (Subprofessional) ----------
    S(2, 1, "Declaration of principles", "According to Article II of the 1987 Constitution, sovereignty resides in:",
      ["the people", "the President", "the Congress", "the Supreme Court"],
      "Article II, Section 1: \"Sovereignty resides in the people and all government authority emanates from them.\""),
    S(2, 1, "Bill of Rights", "In which article of the 1987 Constitution is the Bill of Rights found?",
      ["Article III", "Article II", "Article IV", "Article XIII"],
      "Article III is the Bill of Rights. Article II states principles and policies, Article IV covers citizenship and Article XIII social justice and human rights."),
    S(2, 1, "Executive department", "What is the term of office of the President under the 1987 Constitution?",
      ["Six years, with no reelection", "Four years, with one reelection", "Six years, with one reelection", "Three years, with two reelections"],
      "Article VII, Section 4: the President is elected for a term of six years and is not eligible for any reelection."),
    S(2, 1, "Suffrage", "What is the minimum age to vote under Article V of the 1987 Constitution?",
      ["18 years", "20 years", "21 years", "25 years"],
      "Article V, Section 1 gives suffrage to citizens at least 18 years old who meet the residence requirements."),
    S(2, 2, "Constitutional commissions", "Which three are the constitutional commissions under Article IX?",
      ["Civil Service, Elections, Audit", "Civil Service, Human Rights, Audit", "Elections, Audit, Ombudsman", "Civil Service, Elections, Ombudsman"],
      "Article IX names three independent constitutional commissions: the Civil Service Commission, the Commission on Elections and the Commission on Audit. The Commission on Human Rights is created under Article XIII."),
    S(2, 2, "Bill of Rights", "Under the Bill of Rights, a person under investigation for an offense has the right to:",
      ["remain silent and have counsel", "choose the investigating officer", "be released without bail", "refuse to give his or her name"],
      "Article III, Section 12(1) guarantees the right to be informed of the right to remain silent and to have competent and independent counsel, preferably of one's own choice."),
    S(2, 1, "Language", "What is the national language of the Philippines under the 1987 Constitution?",
      ["Filipino", "Tagalog", "English", "Cebuano"],
      "Article XIV, Section 6: \"The national language of the Philippines is Filipino.\" Filipino and, until otherwise provided by law, English are the official languages."),
    S(2, 2, "Declaration of principles", "Which principle does the 1987 Constitution declare \"inviolable\"?",
      ["Separation of Church and State", "Supremacy of the President", "Public ownership of all land", "Compulsory military service"],
      "Article II, Section 6: \"The separation of Church and State shall be inviolable.\""),
    S(2, 2, "Bill of Rights", "Under the Bill of Rights, no person shall be imprisoned for:",
      ["debt", "theft", "murder", "estafa"],
      "Article III, Section 20: \"No person shall be imprisoned for debt or non-payment of a poll tax.\" Theft, estafa and murder are crimes punished by law."),
    S(2, 2, "History of the Constitution", "On what date was the 1987 Constitution ratified by the Filipino people in a plebiscite?",
      ["February 2, 1987", "February 25, 1986", "October 15, 1986", "January 17, 1973"],
      "The plebiscite was held on February 2, 1987. The Constitutional Commission presented its draft on October 15, 1986, February 25, 1986 ended the EDSA People Power Revolution, and January 17, 1973 is when the 1973 Constitution was proclaimed ratified."),

    # ---------- Drill only ----------
    S(0, 2, "Accountability", "Which officials may be removed from office through impeachment?",
      ["The President and Supreme Court justices", "Senators and members of the House", "Governors and city or municipal mayors", "Department secretaries and bureau heads"],
      "Article XI, Section 2 lists the President, the Vice-President, the members of the Supreme Court, the members of the constitutional commissions and the Ombudsman. Members of Congress are disciplined by their own chamber."),
    S(0, 2, "Declaration of principles", "The 1987 Constitution says the State shall protect and advance the right of the people to:",
      ["a balanced and healthful ecology", "free housing from the government", "a guaranteed government job", "tax-free personal income"],
      "Article II, Section 16: \"The State shall protect and advance the right of the people to a balanced and healthful ecology in accord with the rhythm and harmony of nature.\""),
    S(0, 3, "Article IX-B", "Under Article IX-B, a candidate who has lost in an election may not be appointed to any government office within what period after the election?",
      ["One year", "Six months", "Two years", "Three years"],
      "Article IX-B, Section 6: no candidate who has lost in any election shall, within one year after the election, be appointed to any office in the government or any GOCC."),
]
